import type { Sessao } from '@/core/realtime/estado';

/** Uma bateria do kartódromo: um só sorteio e, dentro dela, a tomada de tempo e a corrida. */
export type Bateria = { chave: string; nome: string; etapas: Sessao[]; atual: Sessao; situacao: 'viva' | 'proxima' | 'encerrada' };

const vivo = (s: Sessao) => s.state === 'em_andamento' || s.state === 'bandeira_final';
const ordem = (s: Sessao) => (s.type === 'classificacao' ? 0 : s.type === 'corrida' ? 1 : 2);
export const nomeEtapa = (s: Sessao) => (s.type === 'classificacao' ? 'Tomada de tempo' : s.type === 'corrida' ? 'Corrida' : s.type === 'treino' ? 'Treino' : s.name ?? 'Etapa');

/** Nome sem a etapa: "BATERIA 18:00 · TOMADA DE TEMPO" vira "BATERIA 18:00". */
export const nomeDaBateria = (nome = '') => nome.split(/\s+[·-]\s+(?=tomada de tempo$|corrida$|treino$)/i)[0].trim();

export function agruparBaterias(sessoes: Sessao[]): Bateria[] {
  const grupos = new Map<string, Sessao[]>();
  for (const s of sessoes) {
    const chave = s.agendaId != null ? `agenda-${s.agendaId}` : `${s.id.slice(0, 10)}-${nomeDaBateria(s.name)}`;
    grupos.set(chave, [...(grupos.get(chave) ?? []), s]);
  }
  return [...grupos].map(([chave, lista]) => {
    const etapas = [...lista].sort((a, b) => ordem(a) - ordem(b));
    const ativas = etapas.filter((s) => s.state !== 'cancelada');
    const atual = ativas.find(vivo) ?? ativas.find((s) => s.state === 'preparando') ?? ativas[ativas.length - 1] ?? etapas[0];
    const situacao = vivo(atual) ? 'viva' : atual.state === 'preparando' ? 'proxima' : 'encerrada';
    return { chave, nome: nomeDaBateria(etapas[0].name), etapas: ativas.length ? ativas : etapas, atual, situacao };
  });
}
